import pytest


def age_at(born: int, now: int) -> int:
    """Whole years elapsed from the birth year `born` to the given year `now`.

    The current year is passed in explicitly; this function never reads the clock.
    Raises ValueError if `born` is later than `now`.
    """
    if born > now:
        raise ValueError("birth year is after current year")
    return now - born


def test_age_at_later_year() -> None:
    assert age_at(1990, 2024) == 34


def test_age_at_same_year_is_zero() -> None:
    assert age_at(2000, 2000) == 0


def test_age_at_one_year_apart() -> None:
    assert age_at(1999, 2000) == 1


def test_age_at_is_deterministic_for_given_now() -> None:
    assert age_at(1980, 2010) == age_at(1980, 2010)


def test_age_at_rejects_birth_after_now() -> None:
    with pytest.raises(ValueError):
        age_at(2025, 2024)
